int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // There are 4 snacks, so each subset can be represented by a 4-bit mask: 0..15.
    // Leaves are all 16 subsets of S.
    //
    // We build a complete binary tree whose leaves are these 16 subsets.
    // Internal nodes are labeled with:
    // A = intersection
    // O = union
    // X = symmetric difference
    //
    // For each internal node, given the set values of its two children (x, y),
    // the parent can become one of:
    // x & y, x | y, x ^ y
    //
    // We count how many fillings of internal nodes produce each possible set at each subtree.
    //
    // Since the tree is fixed and complete with 16 leaves, there are 15 internal nodes.
    // Bottom-up DP on intervals / levels is enough.

    const int N = 16; // number of leaves/subsets
    vector<long long> cur(N, 1), nxt;

    // cur[mask] for level 0 means a leaf fixed to that subset: exactly 1 way.
    // Combine adjacent subtrees level by level.
    // Tree levels: 16 leaves -> 8 -> 4 -> 2 -> 1 root, so 4 merge rounds.

    // At the current stage, we conceptually have blocks of size block.
    // But since every leaf/subtree initially contains each subset exactly once,
    // and all leaves are fixed distinctly, we need DP per subtree position.
    //
    // So instead store DP for each subtree at current level:
    // dp[pos][mask] = number of ways subtree at position pos evaluates to mask.
    vector<vector<long long>> dp;
    dp.reserve(N);

    for (int i = 0; i < N; ++i) {
        vector<long long> v(N, 0);
        v[i] = 1; // leaf i is the subset represented by mask i
        dp.push_back(v);
    }

    while (dp.size() > 1) {
        vector<vector<long long>> ndp;
        for (size_t i = 0; i < dp.size(); i += 2) {
            vector<long long> res(N, 0);
            for (int x = 0; x < N; ++x) if (dp[i][x]) {
                for (int y = 0; y < N; ++y) if (dp[i + 1][y]) {
                    long long ways = dp[i][x] * dp[i + 1][y];
                    res[x & y] += ways; // A
                    res[x | y] += ways; // O
                    res[x ^ y] += ways; // X
                }
            }
            ndp.push_back(move(res));
        }
        dp = move(ndp);
    }

    // All snacks = full set = mask 15.
    cout << dp[0][15] << '\n';
    return 0;
}

