char tokens[200005][5];
int token_cnt;
int token_len[200005];

void tokenize(char *s) {
    int i = 0;
    token_cnt = 0;
    while (s[i]) {
        if (s[i] == 'A' || s[i] == 'O' || s[i] == 'X') {
            tokens[token_cnt][0] = s[i];
            tokens[token_cnt][1] = '\0';
            token_len[token_cnt] = 1;
            token_cnt++;
            i++;
        } else {
            // leaf: read until we hit an operator or end
            int j = 0;
            while (s[i] && s[i] != 'A' && s[i] != 'O' && s[i] != 'X') {
                tokens[token_cnt][j++] = s[i++];
            }
            tokens[token_cnt][j] = '\0';
            token_len[token_cnt] = j;
            token_cnt++;
        }
    }
}

int build_tree(int *idx) {
    int cur = node_count++;
    if (token_len[*idx] > 1 || (tokens[*idx][0] != 'A' && tokens[*idx][0] != 'O' && tokens[*idx][0] != 'X')) {
        // leaf
        leaf[cur] = 1;
        // compute mask
        int mask = 0;
        for (int i = 0; tokens[*idx][i]; i++) {
            if (tokens[*idx][i] == 'a') mask |= 1;
            else if (tokens[*idx][i] == 'b') mask |= 2;
            else if (tokens[*idx][i] == 'c') mask |= 4;
            else if (tokens[*idx][i] == 'd') mask |= 8;
        }
        // store mask in dp base
        for (int m = 0; m < 16; m++) {
            if (m == mask) dp[cur][m] = 1;
            else dp[cur][m] = 0;
        }
        (*idx)++;
        return cur;
    } else {
        leaf[cur] = 0;
        char op = tokens[*idx][0];
        (*idx)++;
        left[cur] = build_tree(idx);
        right[cur] = build_tree(idx);

        // combine
        for (int m1 = 0; m1 < 16; m1++) {
            if (dp[left[cur]][m1] == 0) continue;
            for (int m2 = 0; m2 < 16; m2++) {
                if (dp[right[cur]][m2] == 0) continue;
                int m;
                if (op == 'A') m = m1 & m2;
                else if (op == 'O') m = m1 | m2;
                else m = m1 ^ m2;
                dp[cur][m] = (dp[cur][m] + dp[left[cur]][m1] * dp[right[cur]][m2]) % MOD;
            }
        }
        return cur;
    }
}

