#define MAXN 200005
#define MOD 1000000007LL

typedef long long ll;

typedef struct {
    int left, right;
    int isLeaf;
    int mask;   // for leaf: subset of {a,b,c,d}
} Node;

Node tree[MAXN];
int n;
ll dp[MAXN][16];

int op_apply(int op, int x, int y) {
    if (op == 0) return x & y;      // A
    if (op == 1) return x | y;      // O
    return x ^ y;                   // X
}

void dfs(int u) {
    if (tree[u].isLeaf) {
        for (int i = 0; i < 16; i++) dp[u][i] = 0;
        dp[u][tree[u].mask] = 1;
        return;
    }

    int l = tree[u].left, r = tree[u].right;
    dfs(l);
    dfs(r);

    for (int i = 0; i < 16; i++) dp[u][i] = 0;

    for (int x = 0; x < 16; x++) {
        if (!dp[l][x]) continue;
        for (int y = 0; y < 16; y++) {
            if (!dp[r][y]) continue;
            ll ways = (dp[l][x] * dp[r][y]) % MOD;

            int z;

            z = x & y; // A
            dp[u][z] = (dp[u][z] + ways) % MOD;

            z = x | y; // O
            dp[u][z] = (dp[u][z] + ways) % MOD;

            z = x ^ y; // X
            dp[u][z] = (dp[u][z] + ways) % MOD;
        }
    }
}

int parse_mask(const char *s) {
    int mask = 0;
    for (int i = 0; s[i]; i++) {
        if (s[i] == 'a') mask |= 1 << 0;
        else if (s[i] == 'b') mask |= 1 << 1;
        else if (s[i] == 'c') mask |= 1 << 2;
        else if (s[i] == 'd') mask |= 1 << 3;
    }
    return mask;
}

