def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    tree = data[1]

    # dp[i] = set of possible bitmasks for subtree rooted at node i
    # We'll compute it post-order
    # Represent tree as list: for leaf it's a single bitmask, for internal it's children indices

    # First parse the tree into structure
    # We'll parse using index pointer
    idx = 0
    def parse():
        nonlocal idx
        if idx >= len(tree):
            return None
        if tree[idx] in ('A', 'O', 'X'):
            op = tree[idx]
            idx += 1
            left = parse()
            right = parse()
            return ('internal', op, left, right)
        else:
            # leaf: character a,b,c,d
            leaf_char = tree[idx]
            idx += 1
            mask = 1 << (ord(leaf_char) - ord('a'))
            return ('leaf', mask)

    root = parse()

    def dfs(node):
        if node[0] == 'leaf':
            return {node[1]}
        _, op, left, right = node
        left_set = dfs(left)
        right_set = dfs(right)
        res = set()
        for l in left_set:
            for r in right_set:
                if op == 'A':
                    res.add(l & r)
                elif op == 'O':
                    res.add(l | r)
                else:  # 'X'
                    res.add(l ^ r)
        return res

    possible = dfs(root)
    print(1 if FULL in possible else 0)

