public class Main {
    static final int MOD = 1_000_000_007;
    static int n;
    static char[] tree;
    static long[][][] dp;
    static int[] leafMask;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        tree = new char[n];
        String s = br.readLine().trim();
        for (int i = 0; i < n; i++) {
            tree[i] = s.charAt(i);
        }

        // Build leaf masks: 0..3 correspond to a,b,c,d
        leafMask = new int[n];
        Arrays.fill(leafMask, -1);
        int leafIdx = 0;
        for (int i = 0; i < n; i++) {
            if (tree[i] == 'a' || tree[i] == 'b' || tree[i] == 'c' || tree[i] == 'd') {
                leafMask[i] = 1 << (tree[i] - 'a');
            }
        }

        dp = new long[n][16][2];
        for (int i = 0; i < n; i++) {
            for (int mask = 0; mask < 16; mask++) {
                Arrays.fill(dp[i][mask], -1);
            }
        }

        long result = solve(0, 15, 1); // root must give all snacks (mask 15) and be true
        System.out.println(result);
    }

    static long solve(int node, int targetMask, int wantTrue) {
        if (dp[node][targetMask][wantTrue] != -1) {
            return dp[node][targetMask][wantTrue];
        }

        // Leaf node
        if (leafMask[node] != -1) {
            int actualMask = leafMask[node];
            boolean result = (targetMask & actualMask) == targetMask; // leaf gives exactly its subset
            // For leaf, we want it to produce exactly targetMask? Actually leaf gives fixed set,
            // so it is either equal to targetMask or not.
            // But we are asking: can this leaf evaluate to targetMask with truth value wantTrue?
            // Since leaf has no operator, its truth is fixed: it gives its own set.
            // So if wantTrue == 1, we need targetMask == actualMask.
            // If wantTrue == 0, we need targetMask != actualMask (but that's not how the problem works)
            // Actually the problem: leaf nodes represent subsets, internal nodes are operators.
            // The root gives a set. We want that set to be all snacks.
            // So we never ask for wantTrue = 0 from leaf.
            // So we only call with wantTrue=1 for leaves.
            long res = (targetMask == actualMask) ? 1 : 0;
            dp[node][targetMask][wantTrue] = res;
            return res;
        }

        // Internal node: find children
        int left = 2 * node + 1;
        int right = 2 * node + 2;
        if (left >= n || right >= n) {
            dp[node][targetMask][wantTrue] = 0;
            return 0;
        }

        char op = tree[node];
        long total = 0;

        // Try all possible masks for left and right
        for (int leftMask = 0; leftMask < 16; leftMask++) {
            for (int rightMask = 0; rightMask < 16; rightMask++) {
                int resultMask;
                if (op == 'A') {
                    resultMask = leftMask & rightMask;
                } else if (op == 'O') {
                    resultMask = leftMask | rightMask;
                } else { // 'X'
                    resultMask = leftMask ^ rightMask;
                }

                if (wantTrue == 1 && resultMask != targetMask) continue;
                if (wantTrue == 0 && resultMask == targetMask) continue;

                long waysLeft = solve(left, leftMask, 1);
                long waysRight = solve(right, rightMask, 1);
                if (waysLeft > 0 && waysRight > 0) {
                    total = (total + waysLeft * waysRight) % MOD;
                }
            }
        }

        dp[node][targetMask][wantTrue] = total;
        return total;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static final long MOD = 1_000_000_007L;

    // dp[node][mask] = number of ways for subtree rooted at node to evaluate to subset "mask"
    static long[][] dp;
    static int idx;
    static String s;

    static int parseNode() {
        int my = idx++;
        char ch = s.charAt(pos++);
        if (ch == '(') {
            int left = parseNode();
            pos++; // skip ','
            int right = parseNode();
            pos++; // skip ')'

            for (int lm = 0; lm < 16; lm++) {
                if (dp[left][lm] == 0) continue;
                for (int rm = 0; rm < 16; rm++) {
                    if (dp[right][rm] == 0) continue;
                    long ways = (dp[left][lm] * dp[right][rm]) % MOD;

                    int andMask = lm & rm;
                    int orMask = lm | rm;
                    int xorMask = lm ^ rm;

                    dp[my][andMask] = (dp[my][andMask] + ways) % MOD;
                    dp[my][orMask] = (dp[my][orMask] + ways) % MOD;
                    dp[my][xorMask] = (dp[my][xorMask] + ways) % MOD;
                }
            }
        } else {
            // leaf: one of the subsets of {a,b,c,d}, written as a string of letters,
            // or possibly empty set represented by {}
            int mask = 0;

            if (ch == '{') {
                while (s.charAt(pos) != '}') {
                    char c = s.charAt(pos++);
                    if (c == 'a') mask |= 1;
                    else if (c == 'b') mask |= 2;
                    else if (c == 'c') mask |= 4;
                    else if (c == 'd') mask |= 8;
                }
                pos++; // skip '}'
            } else {
                // if leaves are given directly as strings like "ab", "acd", etc.
                while (true) {
                    if (ch == 'a') mask |= 1;
                    else if (ch == 'b') mask |= 2;
                    else if (ch == 'c') mask |= 4;
                    else if (ch == 'd') mask |= 8;
                    if (pos >= s.length()) break;
                    char nx = s.charAt(pos);
                    if (nx == ',' || nx == ')') break;
                    ch = s.charAt(pos++);
                }
            }
            dp[my][mask] = 1;
        }
        return my;
    }

    static int pos = 0;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String input = fs.next();
        if (input == null) return;

        s = input;
        int n = s.length();
        dp = new long[n + 5][16];
        idx = 0;
        pos = 0;

        int root = parseNode();
        System.out.println(dp[root][15] % MOD);
    }
}
